WITH cte_cao AS ( SELECT cao.* FROM cnsmr_accnt_ownrs cao WHERE cao.cnsmr_accnt_ownrshp_sft_dlt_flg = 'N' ), cte_c AS ( SELECT c.* FROM cnsmr c INNER JOIN cte_cao ON cte_cao.cnsmr_id = c.cnsmr_id ), cte_w AS ( SELECT w.* FROM wrkgrp w INNER JOIN cte_c ON cte_c.wrkgrp_id = w.wrkgrp_id ), cte_d AS ( SELECT d.* FROM dprtmnt d INNER JOIN cte_w ON cte_w.wrkgrp_dprtmnt_id = d.dprtmnt_id ), cte_trans AS ( SELECT trans.* FROM cnsmr_accnt_trnsctn trans INNER JOIN ( SELECT trn.cnsmr_accnt_trnsctn_id FROM cnsmr_accnt_trnsctn trn INNER JOIN ( SELECT cnsmr_accnt_id, MAX(cnsmr_accnt_trnsctn_pst_dt) AS cnsmr_accnt_trnsctn_pst_dt FROM cnsmr_accnt_trnsctn GROUP BY cnsmr_accnt_id ) trn1 ON trn1.cnsmr_accnt_id = trn.cnsmr_accnt_id AND trn1.cnsmr_accnt_trnsctn_pst_dt = trn.cnsmr_accnt_trnsctn_pst_dt ) t ON t.cnsmr_accnt_trnsctn_id = trans.CNSMR_ACCNT_TRNSCTN_ID ), cte_tb_5 AS ( SELECT catg.cnsmr_accnt_id AS cnsmr_accnt_id FROM cnsmr_accnt_tag catg INNER JOIN tag catt ON catt.tag_id = catg.tag_id AND catt.tag_shrt_nm IN ('SIF','SIF1099','SIFGT600','SIFLT600','PIF','PIFFRGV','DCSDPIF','DCSDSIF','LGLPIF','LGLSIF') WHERE catg.cnsmr_accnt_sft_delete_flg = 'N' ) SELECT DISTINCT ca.cnsmr_accnt_id FROM cnsmr_accnt ca INNER JOIN cte_cao cao ON cao.cnsmr_accnt_id = ca.cnsmr_accnt_id INNER JOIN cte_c c ON c.cnsmr_id = cao.cnsmr_id INNER JOIN cte_w w ON c.wrkgrp_id = w.wrkgrp_id INNER JOIN cte_d d ON w.wrkgrp_dprtmnt_id = d.dprtmnt_id LEFT JOIN cte_trans trans ON trans.cnsmr_accnt_id = ca.cnsmr_accnt_id LEFT JOIN cte_tb_5 TB_5 ON ca.cnsmr_accnt_id = TB_5.cnsmr_accnt_id WHERE d.dprtmnt_shrt_nm = 'CNSRCVRY' AND TB_5.cnsmr_accnt_id IS NULL AND ((trans.cnsmr_accnt_trnsctn_pst_dt >= (SELECT DBO.fn_relative_date(GETDATE(), -1, NULL)) AND trans.cnsmr_accnt_pymnt_amnt > 0) OR (CAST(ca.cnsmr_accnt_plcmnt_date AS DATE) = CAST(DBO.GETDATE() AS DATE)));